CREATE OR REPLACE FUNCTION public.is_goods_post(_post public.posts) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT _post.module='vehicle' AND lower(trim(coalesce(_post.vehicle_type,''))) NOT IN ('car','cars','కారు','కార్లు','కార్') $$;
CREATE OR REPLACE FUNCTION public.has_goods_membership(_user uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_allowed(_user) AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.job_post_entitlements e ON e.user_id=p.id JOIN public.membership_payments m ON m.id=e.payment_id WHERE p.id=_user AND p.is_prime AND p.prime_until>(now() AT TIME ZONE 'Asia/Kolkata')::date AND e.starts_at<=now() AND e.ends_at>now() AND m.status='approved' AND m.amount=699 AND m.membership_type='individual') $$;
REVOKE ALL ON FUNCTION public.has_goods_membership(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_goods_membership(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.my_goods_membership() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_goods_membership(auth.uid()) $$;
REVOKE ALL ON FUNCTION public.my_goods_membership() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_goods_membership() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.enforce_paid_job_quota() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.job_expires_at IS DISTINCT FROM OLD.job_expires_at OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.module IS DISTINCT FROM OLD.module OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'POST_IDENTITY_PROTECTED'; END IF; ELSE NEW.job_expires_at:=NULL; END IF; RETURN NEW; END $$;
COMMENT ON TABLE public.job_post_uses IS 'DEPRECATED: historical paid job quota records retained; all new jobs are free without paid quota.';
COMMENT ON TABLE public.job_post_entitlements IS 'Payment-linked monthly periods retained for approved individual 699 goods membership; no new job usage quota applies.';
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _post IS NULL THEN _other=public.support_admin_id() OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs pair JOIN public.posts p ON p.id=pair.post_id WHERE pair.post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) AND (NOT public.is_goods_post(p) OR public.has_goods_membership(auth.uid()))) END $$;
CREATE OR REPLACE FUNCTION public.guard_new_match_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mode text:=current_setting('app.bell_notice',true); BEGIN IF NEW.post_id IS NULL AND NEW.matched_post_id IS NULL THEN RETURN NEW; END IF; IF mode IS NULL OR mode NOT IN('owner','interest') THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.posts WHERE id IN(NEW.post_id,NEW.matched_post_id) AND (visible_after>now() OR job_expires_at<=now() OR status<>'active' OR NOT public.account_allowed(user_id))) THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.posts p WHERE id IN(NEW.post_id,NEW.matched_post_id) AND public.is_goods_post(p)) AND NOT public.has_goods_membership(NEW.user_id) THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; result jsonb; BEGIN SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR (status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF public.is_goods_post(p) AND NOT public.has_goods_membership(auth.uid()) THEN RAISE EXCEPTION 'GOODS_MEMBERSHIP_REQUIRED'; END IF; result:=jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date); IF public.is_goods_post(p) AND p.show_contact THEN result:=result||jsonb_build_object('public_photo',p.public_photo,'public_brand',p.public_brand,'contact_phone',p.contact_phone); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.get_post_details(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_post_details(uuid) TO anon,authenticated,service_role;
REVOKE SELECT ON public.posts FROM anon,authenticated;
REVOKE SELECT(description,contact_phone,public_photo,public_brand) ON public.posts FROM anon,authenticated;
GRANT SELECT(id,user_id,module,kind,title,location,skill,salary,from_place,to_place,trip_date,vehicle_type,goods_type,status,created_at,show_contact,category,area_scope,district,state,service_type,capacity_tons,job_expires_at,visible_after,visibility_notified_at) ON public.posts TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.notify_matches(_post_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; m record; n integer:=0; notice uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND user_id=auth.uid() AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()); IF p.id IS NULL THEN RAISE EXCEPTION 'OWN_VISIBLE_POST_REQUIRED'; END IF; IF public.is_goods_post(p) AND NOT public.has_goods_membership(auth.uid()) THEN RAISE EXCEPTION 'GOODS_MEMBERSHIP_REQUIRED'; END IF; PERFORM set_config('app.bell_notice','owner',true); FOR m IN SELECT DISTINCT ON(user_id) candidate.* FROM public.posts candidate WHERE public.posts_match_area(p,candidate) AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) ORDER BY user_id,created_at DESC LOOP IF n>=3 THEN EXIT; END IF; PERFORM 1 FROM public.profiles WHERE id=m.user_id FOR UPDATE; IF public.can_notify(m.user_id) AND NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=m.user_id AND matched_post_id=p.id AND created_at>now()-interval '5 minutes') THEN notice:=NULL; INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,p.id,'గంట కొట్టారు · Bell: '||CASE WHEN p.module='vehicle' THEN coalesce(p.vehicle_type,'వాహనం') ELSE coalesce(p.skill,'ఉద్యోగం') END) RETURNING id INTO notice; IF notice IS NOT NULL THEN n:=n+1; END IF; END IF; END LOOP; PERFORM set_config('app.bell_notice','',true); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.ring_post(_post_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id); IF p.id IS NULL OR p.user_id=caller THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF public.is_goods_post(p) AND NOT public.has_goods_membership(auth.uid()) THEN RAISE EXCEPTION 'GOODS_MEMBERSHIP_REQUIRED'; END IF; INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,caller,p.user_id) ON CONFLICT DO NOTHING; PERFORM set_config('app.bell_notice','interest',true); PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; IF public.can_notify(p.user_id) THEN INSERT INTO public.notifications(user_id,post_id,message) VALUES(p.user_id,p.id,'మీ ప్రకటనపై సమాచారం కోరారు · Someone rang your post bell'); END IF; IF NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id AND sender_id=caller AND receiver_id=p.user_id) THEN INSERT INTO public.messages(sender_id,receiver_id,post_id,body) VALUES(caller,p.user_id,p.id,'మీ ప్రకటనపై సమాచారం కావాలి · Interested in your post'); END IF; PERFORM set_config('app.bell_notice','',true); RETURN p.user_id; END $$;